// TypeScript (override idemp key)
import Redwood from '@redwood/sdk'
const client = new Redwood()
// override idempotency key for dedupe across retries
const resp = await client.requests.create({ body }, { idempotencyKey: 'order-9876' })

// Streaming reconnect example
const stream = client.chat.stream({ conversationId: 'c-123' })
stream.on('data', (chunk) => handle(chunk))
stream.on('end', () => console.log('finished'))
// SDK will attach resumeToken to stream metadata and attempt resume within 5s using exponential backoff jitter

// Go (explicit control and check resume result)
client := redwood.NewClient(nil)
resp, err := client.CreateDocument(context.Background(), &redwood.CreateDocumentRequest{Text: payload})
if err != nil { /* handle */ }

// streaming: obtain a StreamHandle that exposes Resume() returning (resumed bool, err error)
sh := client.ChatStream(ctx, "c-123")
for {
    chunk, ok := sh.Recv()
    if !ok {
       resumed, rerr := sh.Resume(context.Background())
       if rerr != nil || !resumed {
           break
       }
       continue
    }
    handle(chunk)
}
